//! 🤝️ Actual original Host input and guest root/ledger allocations conserve each issued turn.
use semio_framework_actor::retained_turn::{ActorGuestPhase,OriginalActorInput,RetainedTurnInput};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_actor::retained_turn::context as guest_context;
fn grant(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_public_actor_paired_admission_retains_exact_host_input_and_native_guest_births(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:grant(&fixture["originalGrant"])};let mut source:Vec<u8>=Vec::with_capacity(97);source.extend_from_slice(&[81;7]);let pointer=source.as_ptr();let(mut host,heap)=observe(||OriginalActorInput::new(source,incoming).ok().unwrap());assert_eq!(heap,(0,0));let mut guest=guest_context::OriginalActorContext::new((),incoming).ok().unwrap();let mut births=0;for index in 0..6{if index>0{host.receive_next_issued(incoming).unwrap()}let mut policy=grant(if index==5{&fixture["bodyPolicy"]}else{&fixture["guestPolicy"]});if index==0{policy.maximum_capacity_bytes=0}let checked=host.checkout_guest(policy).unwrap().unwrap();assert!(host.checkout_guest(policy).is_err());let(admission,heap)=observe(||guest.admit_step(checked).unwrap());assert_eq!(heap,(admission.progress.retained_capacity_bytes,0));births+=admission.progress.retained_capacity_bytes;let mut progress=admission.progress;let phase=if index==5{assert!(admission.ready);let mut recipient=RetainedCloneProgress::default();let mut target=[0;7];let(_,heap)=observe(||{let mut cx=guest.borrow_context(checked,semio_framework_job::StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us).unwrap();target.copy_from_slice(host.original().unwrap());cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap()});assert_eq!(heap,(0,0));assert_eq!(target,[81;7]);progress=recipient;ActorGuestPhase::Dispatched}else if admission.ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending};let receipt=checked.return_original(progress).unwrap();host.receive_guest(receipt,phase).unwrap();assert!(host.receive_guest(receipt,phase).is_err());assert_eq!(host.original().unwrap().as_ptr(),pointer);assert_eq!(progress.copied_items,fixture["spent"][index]["items"].as_u64().unwrap()as usize);assert_eq!(progress.copied_bytes,fixture["spent"][index]["copy"].as_u64().unwrap()as usize);assert_eq!(progress.retained_capacity_bytes,fixture["spent"][index]["capacity"].as_u64().unwrap()as usize);let parent=host.return_actor_turn().unwrap();assert!(host.return_actor_turn().is_err());incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};}assert_eq!(serde_json::to_value(incoming.grant).unwrap(),serde_json::json!({"maximumItems":28,"maximumCopyBytes":25,"maximumCapacityBytes":3872,"maximumReleaseBytes":4096,"maximumDepth":8}));assert_eq!(births,224);let source=host.take_dispatched_input().unwrap().unwrap();assert_eq!(source.as_ptr(),pointer);host.receive_next_issued(incoming).unwrap();let close=grant(&fixture["closePolicy"]);let checked=host.checkout_guest(close).unwrap().unwrap();let(_,heap)=observe(||drop(source));assert_eq!(heap,(0,97));host.receive_guest(checked.return_original(RetainedCloneProgress{copied_items:1,released_bytes:97,..Default::default()}).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};guest.take_input().unwrap();let mut released=0;let mut turns=0;while !guest.terminal_is_empty(){host.receive_next_issued(incoming).unwrap();let checked=host.checkout_guest(close).unwrap().unwrap();let(step,heap)=observe(||guest.close_step(checked).unwrap());let progress=step.progress();assert_eq!(heap,(0,progress.released_bytes));released+=progress.released_bytes;host.receive_guest(checked.return_original(progress).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};turns+=1;assert!(turns<16)}assert_eq!(released,births);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));eprintln!("[DEBUG] actual paired Host source97 pointer={pointer:p} guest root64 ledger128 source32 deniesheap0 bodycopy7,one original guest checkout and Actor return per epoch,finite original32items no renewal,source97 and guest224 physical releases funded in separate turns terminalDrop0");}

#[test]
fn original_public_actor_guest_call_returns_actual_failed_body_receipt_and_paid_same_context_close(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:grant(&fixture["originalGrant"])};let mut source:Vec<u8>=Vec::with_capacity(97);source.extend_from_slice(&[81;7]);let pointer=source.as_ptr();let mut host=OriginalActorInput::new(source,incoming).ok().unwrap();let mut guest=guest_context::OriginalActorContextSlot::empty();let mut capacity=0;for index in 0..7{if index!=0{host.receive_next_issued(incoming).unwrap()}let mut policy=grant(if index==6{&fixture["bodyPolicy"]}else{&fixture["guestPolicy"]});if index<2{policy.maximum_capacity_bytes=0}let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=RetainedCloneProgress::default();let(receipt,phase,heap)=if index==6{let(call,heap)=observe(||guest.dispatch_step(checked,semio_framework_job::StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,|cx|{let mut target=[0;7];target.copy_from_slice(host.original().unwrap());assert_eq!(target,[81;7]);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap();Err::<(),_>("original semantic refusal")}));assert!(matches!(call.result,Err(guest_context::OriginalActorCallError::Semantic("original semantic refusal"))));assert_eq!(call.receipt_spent,recipient);assert_eq!(call.receipt_spent,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});(call.receipt().unwrap(),ActorGuestPhase::Dispatched,heap)}else{let(call,heap)=observe(||guest.admit_step(checked));let receipt=call.receipt().unwrap();let phase=if call.result.unwrap().ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending};(receipt,phase,heap)};assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));capacity+=receipt.spent.retained_capacity_bytes;host.receive_guest(receipt,phase).unwrap();assert_eq!(host.original().unwrap().as_ptr(),pointer);let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};}assert_eq!(capacity,224);assert_eq!(incoming.grant.maximum_items,27);assert_eq!(incoming.grant.maximum_copy_bytes,25);assert_eq!(incoming.grant.maximum_capacity_bytes,3872);let source=host.take_dispatched_input().unwrap().unwrap();host.receive_next_issued(incoming).unwrap();let close=grant(&fixture["closePolicy"]);let checked=host.checkout_guest(close).unwrap().unwrap();let(_,heap)=observe(||drop(source));assert_eq!(heap,(0,97));host.receive_guest(checked.return_original(RetainedCloneProgress{copied_items:1,released_bytes:97,..Default::default()}).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};let mut released=0;let mut turns=0;while !guest.terminal_is_empty(){host.receive_next_issued(incoming).unwrap();let checked=host.checkout_guest(close).unwrap().unwrap();let(call,heap)=observe(||guest.close_step(checked));let receipt=call.receipt().unwrap();assert!(call.result.is_ok());assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));released+=receipt.spent.released_bytes;host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};turns+=1;assert!(turns<16)}assert_eq!(released,capacity);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));eprintln!("[DEBUG] actual caller failure keeps original Host source97 pointer={pointer:p},same paid root64/ledger128/source32; semantic Err returns exact external items1/copy7,context binding yields and closes separately under original32 item authority; native terminalDrop0");}

